import { type Dispatch, type SetStateAction } from 'react';
import { type FieldLibrary } from '@divi/types';
export type UseDynamicContent = <TOnChangeCallback extends UseDynamicContentValidOnChangeCallbacks>(props: UseDynamicContentProps<TOnChangeCallback>) => UseDynamicContentReturn;
export type UseDynamicContentValidOnChangeCallbacks = FieldLibrary.Text.Props['onChange'] | FieldLibrary.Upload.OnChangeCallback;
export type UseDynamicContentProps<TOnChangeCallback> = {
    initialValue: string | null;
    onChange: TOnChangeCallback;
};
export type UseDynamicContentReturn = {
    dynamicContent: DynamicContentValue;
    dynamicContentSettingsModalProps: {
        saveDynamicContent: () => void;
        setPopupModalValue: Dispatch<SetStateAction<Record<string, unknown>>>;
        popupModalValue: Record<string, unknown>;
        isPopupModalOpen: boolean;
        setIsPopupModalOpen: Dispatch<SetStateAction<boolean>>;
        editingDynamicContentName: string;
        setEditingDynamicContentName: Dispatch<SetStateAction<string>>;
    };
    dynamicContentButtonProps: {
        setEditingDynamicContentName: Dispatch<SetStateAction<string>>;
        setIsPopupModalOpen: Dispatch<SetStateAction<boolean>>;
        saveDynamicContent: () => void;
    };
    dynamicContentOnEdit: () => void;
    dynamicContentOnDelete: () => void;
};
export type DynamicContentValue = {
    type: string;
    value: {
        name: string;
        settings: Record<string, unknown>;
    };
};
export type DynamicContentData = {
    name: string;
    settings: Record<string, unknown>;
};
